CREATE POLICY "Owner removes unattached partner uploads" ON storage.objects FOR DELETE TO authenticated USING(bucket_id='partner-documents' AND split_part(name,'/',1)=auth.uid()::text AND NOT EXISTS(SELECT 1 FROM public.partner_applications a WHERE name IN (a.cnic_image_url,a.shop_image_url,a.extra->>'cnic_back_url',a.extra->>'selfie_url',a.extra->>'cheque_path')) AND NOT EXISTS(SELECT 1 FROM public.rider_verifications v WHERE name IN (v.front_url,v.back_url,v.selfie_url)) AND NOT EXISTS(SELECT 1 FROM public.partner_kyc_checks k WHERE name IN (k.front_path,k.back_path,k.selfie_path)) AND NOT EXISTS(SELECT 1 FROM public.rider_remittances m WHERE m.receipt_url=name));